<?php $rows=$pdo->query('SELECT c.*,u.unit_code,u.category FROM condition_events c JOIN units u ON u.id=c.unit_id ORDER BY event_date DESC,c.id DESC')->fetchAll();$units=$pdo->query('SELECT id,unit_code FROM units ORDER BY unit_code')->fetchAll();?>
<div class="card panel"><h3>Input Condition Monitoring</h3><form class="form-grid compact" method="post" action="actions/save_condition.php"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><label>Unit<select name="unit_id"><?php foreach($units as $u):?><option value="<?=$u['id']?>"><?=e($u['unit_code'])?></option><?php endforeach;?></select></label><label>Tanggal<input type="date" name="event_date" value="<?=date('Y-m-d')?>"></label><label>Status<select name="status"><?php foreach(['Ready for Use','Breakdown','Downtime'] as $s):?><option><?=$s?></option><?php endforeach;?></select></label><label>Jam Mulai<input type="time" name="start_time"></label><label>Jam Selesai<input type="time" name="end_time"></label><label>Penyebab<input name="cause"></label><label>Tindakan<input name="action_taken"></label><div><button class="btn primary">Simpan</button></div></form></div>
<div class="card panel"><h3>Riwayat Condition Monitoring</h3><table><thead><tr><th>Tanggal</th><th>Unit</th><th>Kategori</th><th>Status</th><th>Durasi</th><th>Penyebab</th><th>Tindakan</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['event_date'])?></td><td><?=e($r['unit_code'])?></td><td><?=e($r['category'])?></td><td><span class="status <?=status_class($r['status'])?>"><?=e($r['status'])?></span></td><td><?=e((string)$r['duration_hours'])?> jam</td><td><?=e($r['cause'])?></td><td><?=e($r['action_taken'])?></td></tr><?php endforeach;?></tbody></table></div>
